import java.net.http.*;import java.net.*;import java.nio.file.*;import java.util.*;
public class OcrScan{static String boundary="----ThamudicOCR";public static void main(String[]a)throws Exception{if(a.length<1){System.err.println("usage: OcrScan image [engine]");System.exit(2);}String engine=a.length>1?a[1]:"auto";byte[] data=Files.readAllBytes(Path.of(a[0]));String head="--"+boundary+"\r\nContent-Disposition: form-data; name=\"file\"; filename=\""+Path.of(a[0]).getFileName()+"\"\r\nContent-Type: application/octet-stream\r\n\r\n";byte[] h=head.getBytes();byte[] tail=("\r\n--"+boundary+"--\r\n").getBytes();byte[] body=new byte[h.length+data.length+tail.length];System.arraycopy(h,0,body,0,h.length);System.arraycopy(data,0,body,h.length,data.length);System.arraycopy(tail,0,body,h.length+data.length,tail.length);var r=HttpClient.newHttpClient().send(HttpRequest.newBuilder(URI.create("http://127.0.0.1:8010/api/ocr/scan?engine="+URLEncoder.encode(engine,"UTF-8"))).header("Content-Type","multipart/form-data; boundary="+boundary).POST(HttpRequest.BodyPublishers.ofByteArray(body)).build(),HttpResponse.BodyHandlers.ofString());System.out.println(r.body());}}
